'use strict';
const api='../api/index.php';const $=id=>document.getElementById(id);const urlKioskCode=(new URLSearchParams(location.search).get('kiosk')||'').trim().toUpperCase();const kioskCode=urlKioskCode||(localStorage.getItem('kqcenter_kiosk_template')||'').trim().toUpperCase();let kioskConfig=null,kioskMenu=[],selectedDepartmentId=0,selectedServiceId=0,selectedMenuItemId=0;let stream=null,scanMode='checkin',idleTimer,finishTimer,finishSeconds=60,currentRequestKey='',lastCitizenId='',lastCardName='',latchedCardId='',autoCardBusy=false,issuingTicket=false;
const panels=['homePanel','servicePanel','identifyPanel','scanPanel','walkinPanel','ticketPanel'];let lookupMethod='code';
function thaiClock(){const now=new Date();$('clockTime').textContent=new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now)+' น.';$('clockDate').textContent=new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{timeZone:'Asia/Bangkok',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now)}
thaiClock();setInterval(thaiClock,30000);
function resetIdle(){clearTimeout(idleTimer);if(!$('homePanel').classList.contains('hidden'))return;idleTimer=setTimeout(()=>show('homePanel'),90000)}
['pointerdown','keydown'].forEach(name=>document.addEventListener(name,resetIdle,{passive:true}));
function clearPrivateData(){$('scanToken').value='';$('lookupValue').value='';$('scanError').classList.add('hidden');$('lookupError').classList.add('hidden');$('lookupResults').classList.add('hidden');$('walkinError').classList.add('hidden');$('readerState').textContent='พร้อมเชื่อมต่อ Smart Card Bridge';$('patientSummary').classList.add('hidden');$('existingQueueModal').classList.add('hidden');lastCitizenId='';lastCardName='';currentRequestKey='';issuingTicket=false;clearInterval(finishTimer)}
function updatePatientSummary(){const name=lastCardName||'ผู้รับบริการไม่ใช้บัตรประชาชน';const identity=lastCitizenId?`เลขบัตรประชาชน •••••••••${lastCitizenId.slice(-4)}`:'เจ้าหน้าที่ห้องบัตรจะตรวจสอบข้อมูลอีกครั้ง';$('patientSummaryName').textContent=name;$('patientSummaryId').textContent=identity;$('slotPatientName').textContent=name;$('slotPatientId').textContent=identity;$('patientSummary').classList.remove('hidden')}
async function continueNewQueue(){await kioskConfigReady;renderKioskMenu(null);$('existingQueueModal').classList.add('hidden');show('servicePanel')}
function showExistingQueues(rows){$('existingQueueList').innerHTML=rows.map((row,index)=>`<article class="existing-queue-item"><span><small>คิวเดิม ${escapeHtml(row.start_time.slice(0,5))}–${escapeHtml(row.end_time.slice(0,5))} น.</small><strong>${escapeHtml(row.queue_no)} · ${escapeHtml(row.department_name)}</strong><em>${escapeHtml(row.service_name||'บริการทั่วไป')}</em></span><button type="button" class="touch-button primary" data-reprint-index="${index}">พิมพ์ใหม่</button></article>`).join('');$('existingQueueModal').classList.remove('hidden');$('existingQueueList').querySelectorAll('[data-reprint-index]').forEach(button=>button.onclick=async()=>{setBusy(button,true);try{const row=rows[+button.dataset.reprintIndex];const body=await request('kiosk-check-in',{token:row.public_id});$('existingQueueModal').classList.add('hidden');renderTicket(body.ticket)}catch(error){toast(error.message);setBusy(button,false,'พิมพ์ใหม่')}})}
async function acceptCard(card){lastCitizenId=card.citizen_id;lastCardName=card.display_name||'ผู้ถือบัตร';$('readerState').textContent=`อ่านบัตรสำเร็จ · CID •••••••••${lastCitizenId.slice(-4)}`;updatePatientSummary();toast('อ่านบัตรสำเร็จ');await kioskConfigReady;try{const body=await request('kiosk-lookup',{method:'citizen',value:lastCitizenId});const existing=body.data.filter(row=>row.queue_no);if(existing.length){showExistingQueues(existing);return}}catch{}await continueNewQueue()}
function show(id){panels.forEach(x=>$(x).classList.toggle('hidden',x!==id));if(id!=='scanPanel')stopCamera();if(id==='homePanel')clearPrivateData();if(id==='walkinPanel')loadSlots();resetIdle()}
function configureScan(mode){scanMode=mode;const status=mode==='status';$('scanEyebrow').textContent=status?'QUEUE STATUS':'ONLINE CHECK-IN';$('scanTitle').textContent=status?'ตรวจสอบสถานะคิว':'เช็กอินรายการจอง';$('scanSubtitle').textContent=status?'สแกน QR จากใบคิวหรือ K-QOnline เพื่อดูสถานะ':'นำ QR จาก K-QOnline มาสแกนที่ช่องด้านล่าง';$('scanSubmit').textContent=status?'ดูสถานะคิว':'ยืนยันเช็กอิน';$('scanSubmit').value=mode}
async function loadKioskConfig(){if(!kioskCode)return;try{const response=await fetch(`${api}?action=public-kiosk-config&code=${encodeURIComponent(kioskCode)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'โหลดการตั้งค่า Kiosk ไม่สำเร็จ');kioskConfig=body.template;kioskMenu=body.data||[];$('kioskPointName').textContent=kioskConfig.name;$('kioskBuildingLabel').textContent=kioskConfig.building_name+(kioskConfig.location_label?` · ${kioskConfig.location_label}`:'');renderKioskMenu(null)}catch(error){toast(error.message)}}
function renderKioskMenu(parentId=null){if(!kioskConfig)return;const items=kioskMenu.filter(item=>parentId===null?!item.parent_id:+item.parent_id===+parentId);$('kioskMenuTitle').textContent=parentId===null?'เลือกแผนกหรือจุดบริการ':(kioskMenu.find(x=>+x.id===+parentId)?.label||'เลือกบริการ');$('kioskMenuSubtitle').textContent='ระบบแสดงเฉพาะปุ่มที่เปิดใช้งานตามอาคารและช่วงเวลานี้';$('serviceChoices').classList.toggle('menu-empty',!items.length);$('serviceChoices').innerHTML=(parentId!==null?'<button type="button" class="kiosk-menu-back" data-menu-back>← กลับเมนูหลัก</button>':'')+(items.length?items.map(item=>{const hasChildren=kioskMenu.some(x=>+x.parent_id===+item.id);return `<button type="button" class="service-choice dynamic-service ${hasChildren?'child-menu':''}" data-kiosk-item="${item.id}"><i>${escapeHtml(item.icon||'Q')}</i><span><small>${hasChildren?'เลือกเมนูย่อย':escapeHtml(item.department_name||'จุดบริการ')}</small><strong>${escapeHtml(item.label)}</strong><em>${escapeHtml(item.subtitle||item.service_name||'แตะเพื่อเลือกบริการ')}</em></span><b>›</b></button>`}).join(''):'<div class="kiosk-menu-empty">ขณะนี้ยังไม่มีบริการที่เปิดรับที่จุด Kiosk นี้<br>กรุณาติดต่อเจ้าหน้าที่</div>');$('serviceChoices').querySelector('[data-menu-back]')?.addEventListener('click',()=>renderKioskMenu(null));$('serviceChoices').querySelectorAll('[data-kiosk-item]').forEach(button=>button.onclick=()=>selectKioskMenu(+button.dataset.kioskItem))}
function selectKioskMenu(id){const item=kioskMenu.find(x=>+x.id===id);if(!item)return;if(kioskMenu.some(x=>+x.parent_id===id)){renderKioskMenu(id);return}selectedMenuItemId=id;let target=item;selectedDepartmentId=0;selectedServiceId=0;while(target){selectedServiceId=selectedServiceId||(+target.service_id||0);selectedDepartmentId=selectedDepartmentId||(+target.department_id||0);target=target.parent_id?kioskMenu.find(x=>+x.id===+target.parent_id):null}if(!selectedDepartmentId&&!selectedServiceId){toast('ปุ่มนี้ยังไม่ได้ผูกกับแผนกหรือบริการ');return}currentRequestKey='';updatePatientSummary();show('walkinPanel')}
const kioskConfigReady=loadKioskConfig();
function resetKioskSettings(){$('kioskSettingsLogin').reset();$('kioskTemplateForm').reset();$('kioskSettingsLogin').classList.remove('hidden');$('kioskTemplateForm').classList.add('hidden');$('kioskSettingsError').classList.add('hidden');$('kioskSettingsDescription').textContent='ยืนยันบัญชีผู้มีสิทธิ์ก่อนเลือกจุดบริการ';$('kioskTemplateSelect').innerHTML=''}
function closeKioskSettings(){resetKioskSettings();$('kioskSettingsModal').classList.add('hidden')}
$('kioskSettingsButton').onclick=()=>{resetKioskSettings();$('kioskSettingsModal').classList.remove('hidden');setTimeout(()=>$('kioskAdminUsername').focus(),50)};
$('closeKioskSettings').onclick=closeKioskSettings;
$('createAnotherQueue').onclick=continueNewQueue;$('cancelExistingQueue').onclick=()=>{$('existingQueueModal').classList.add('hidden');show('homePanel')};
$('kioskSettingsLogin').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');setBusy(button,true);$('kioskSettingsError').classList.add('hidden');try{const response=await fetch(`${api}?action=kiosk-template-selector-auth`,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('kioskAdminUsername').value,password:$('kioskAdminPassword').value})});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่มีสิทธิ์เปลี่ยนจุดบริการ Kiosk');if(!body.data.length)throw new Error('ยังไม่มีจุดบริการ Kiosk ที่เปิดใช้งาน');$('kioskTemplateSelect').innerHTML=body.data.map(item=>`<option value="${escapeHtml(item.code)}" ${item.code===kioskCode?'selected':''}>${escapeHtml(item.name)} · ${escapeHtml(item.building_name)}${item.location_label?` · ${escapeHtml(item.location_label)}`:''}</option>`).join('');$('kioskSettingsLogin').classList.add('hidden');$('kioskTemplateForm').classList.remove('hidden');$('kioskSettingsDescription').textContent=`ยืนยันสิทธิ์แล้ว: ${body.user.display_name}`}catch(error){$('kioskSettingsError').textContent=error.message;$('kioskSettingsError').classList.remove('hidden')}finally{setBusy(button,false,'ยืนยันสิทธิ์')}};
$('kioskTemplateForm').onsubmit=async event=>{event.preventDefault();const code=$('kioskTemplateSelect').value;if(!code)return;localStorage.setItem('kqcenter_kiosk_template',code);await closeKioskSettings();const url=new URL(location.href);url.searchParams.set('kiosk',code);url.searchParams.set('v',Date.now().toString());location.replace(url.href)};
document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>{if(button.dataset.mode)configureScan(button.dataset.mode);show(button.dataset.open);if(button.dataset.open==='identifyPanel'&&lastCitizenId)lookupBooking('citizen',lastCitizenId)});
document.querySelectorAll('[data-home]').forEach(button=>button.onclick=()=>show('homePanel'));$('brandHome').onclick=()=>show('homePanel');$('finishButton').onclick=()=>show('homePanel');$('printButton').onclick=()=>window.print();
$('quickSmartcard').onclick=()=>{$('smartcardButton').click()};$('noCardButton').onclick=async()=>{lastCitizenId='';lastCardName='ผู้รับบริการไม่ใช้บัตรประชาชน';updatePatientSummary();await kioskConfigReady;renderKioskMenu(null);show('servicePanel')};
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800)}
async function checkBridge(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800);try{const response=await fetch('http://127.0.0.1:17890/health',{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error();$('bridgeState').textContent='เครื่องอ่านบัตรพร้อมใช้งาน';$('bridgeState').closest('.kiosk-place').classList.remove('offline');return true}catch{$('bridgeState').textContent='Bridge ไม่ตอบสนอง · Watchdog กำลังกู้คืน';$('bridgeState').closest('.kiosk-place').classList.add('offline');return false}finally{clearTimeout(timer)}}
$('restartBridge').onclick=async()=>{const button=$('restartBridge');button.disabled=true;$('bridgeState').textContent='กำลังรีสตาร์ต Smart Card…';try{const healthy=await checkBridge();if(healthy)await fetch('http://127.0.0.1:17890/restart',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).catch(()=>{});await new Promise(resolve=>setTimeout(resolve,2500));for(let attempt=0;attempt<6;attempt++){if(await checkBridge()){toast('Smart Card Bridge พร้อมใช้งานแล้ว');return}await new Promise(resolve=>setTimeout(resolve,1000))}toast('Watchdog จะลองเริ่มระบบใหม่ภายใน 1 นาที')}finally{button.disabled=false}};
checkBridge();setInterval(checkBridge,30000);
async function autoDetectCard(){if(autoCardBusy||!navigator.onLine||$('homePanel').classList.contains('hidden'))return;autoCardBusy=true;try{const response=await fetch('http://127.0.0.1:17890/read',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const body=await response.json();const card=body.data;if(!response.ok||!card?.citizen_id){latchedCardId='';return}if(card.citizen_id===latchedCardId)return;latchedCardId=card.citizen_id;await acceptCard(card)}catch{latchedCardId=''}finally{autoCardBusy=false}}
setInterval(autoDetectCard,1500);setTimeout(autoDetectCard,500);
$('helpButton').onclick=()=>toast('ส่งสัญญาณเรียกเจ้าหน้าที่แล้ว กรุณารอสักครู่');$('accessibilityButton').onclick=()=>{document.body.classList.toggle('large-text');toast(document.body.classList.contains('large-text')?'เปิดตัวอักษรขนาดใหญ่แล้ว':'กลับเป็นตัวอักษรขนาดปกติแล้ว')};
document.querySelectorAll('[data-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.key;if(key==='clear')$('scanToken').value='';else if(key==='back')$('scanToken').value=$('scanToken').value.slice(0,-1);else $('scanToken').value+=key;$('scanToken').focus()});
function tokenFrom(value){const raw=value.trim();try{const url=new URL(raw);return url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{return raw}}
async function request(action,payload){const response=await fetch(`${api}?action=${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่สามารถดำเนินการได้');return body}
function setBusy(button,busy,label){button.disabled=busy;if(!button.dataset.label)button.dataset.label=button.textContent;button.textContent=busy?'กำลังดำเนินการ…':(label||button.dataset.label)}
$('scanForm').onsubmit=async event=>{event.preventDefault();const token=tokenFrom($('scanToken').value);$('scanError').classList.add('hidden');if(scanMode==='status'){location.href=`status.html?t=${encodeURIComponent(token)}`;return}setBusy($('scanSubmit'),true);try{const body=await request('kiosk-check-in',{token});renderTicket(body.ticket)}catch(error){$('scanError').textContent=error.message;$('scanError').classList.remove('hidden')}finally{setBusy($('scanSubmit'),false,'ยืนยันเช็กอิน')}};
function todayIso(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=type=>parts.find(x=>x.type===type).value;return `${get('year')}-${get('month')}-${get('day')}`}
async function loadSlots(){$('slotCards').innerHTML='<div class="loading-card">กำลังตรวจสอบช่วงลงทะเบียน…</div>';$('walkinError').classList.add('hidden');try{const query=new URLSearchParams({action:'public-slots',date:todayIso()});if(kioskCode)query.set('kiosk',kioskCode);if(selectedDepartmentId)query.set('department_id',selectedDepartmentId);if(selectedServiceId)query.set('service_id',selectedServiceId);const response=await fetch(`${api}?${query}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);if(!body.data.length){$('slotCards').innerHTML='<section class="slot-unavailable" role="alert" aria-live="assertive"><span class="slot-unavailable-icon" aria-hidden="true">!</span><div><small>ไม่สามารถออกบัตรคิวได้ในขณะนี้</small><h2>วันนี้ไม่มีช่วงลงทะเบียน<br>ที่ยังรับคิวเพิ่ม</h2><strong>กรุณาติดต่อเจ้าหน้าที่ห้องบัตร</strong><p>เจ้าหน้าที่จะตรวจสอบช่วงเวลาและแนะนำจุดบริการที่เหมาะสมให้ท่าน</p></div></section>';return}$('slotCards').innerHTML=body.data.map(x=>`<button type="button" class="slot-card" data-slot="${x.id}"><span>${x.start_time.slice(0,5)}–${x.end_time.slice(0,5)} น.</span><strong>${escapeHtml(x.department_name)}</strong><small>${escapeHtml(x.service_name||'บริการทั่วไป')} · แตะเพื่อรับและพิมพ์บัตรคิว</small><em><span>รับได้อีก</span><b>${Number(x.available_count)} คิว</b></em></button>`).join('');document.querySelectorAll('.slot-card').forEach(card=>card.onclick=()=>issueWalkinQueue(card))}catch(error){$('slotCards').innerHTML=`<div class="loading-card">${escapeHtml(error.message)}</div>`}}
async function issueWalkinQueue(card){if(issuingTicket)return;issuingTicket=true;$('walkinError').classList.add('hidden');document.querySelectorAll('.slot-card').forEach(button=>button.disabled=true);card.classList.add('selected');card.querySelector('small').textContent='กำลังออกบัตรคิว…';if(!currentRequestKey)currentRequestKey=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;try{const body=await request('kiosk-walk-in',{slot_id:+card.dataset.slot,menu_item_id:selectedMenuItemId,customer_name:lastCardName||'ผู้รับบริการไม่ใช้บัตรประชาชน',customer_phone:'',citizen_id:lastCitizenId,idempotency_key:currentRequestKey});renderTicket(body.ticket)}catch(error){issuingTicket=false;await loadSlots();$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}}
function escapeHtml(value){const node=document.createElement('span');node.textContent=value??'';return node.innerHTML}
document.querySelectorAll('[data-method]').forEach(button=>button.onclick=()=>{lookupMethod=button.dataset.method;document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('active',x===button));const config={code:['กรอกรหัสคิวหรือรหัสยืนยัน','ตัวอย่าง KQ-261016-ABC123','text'],citizen:['กรอกเลขบัตรประชาชน 13 หลัก','X-XXXX-XXXXX-XX-X','numeric'],phone:['กรอกหมายเลขโทรศัพท์','0XX-XXX-XXXX','tel']}[lookupMethod];$('lookupLabel').childNodes[0].textContent=config[0];$('lookupValue').placeholder=config[1];$('lookupValue').inputMode=config[2];$('lookupValue').value='';$('lookupResults').classList.add('hidden');$('lookupError').classList.add('hidden')});
async function lookupBooking(method,value){setBusy($('lookupSubmit'),true);$('lookupError').classList.add('hidden');$('lookupResults').classList.add('hidden');try{const body=await request('kiosk-lookup',{method,value});renderLookupResults(body.data,method,value)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}finally{setBusy($('lookupSubmit'),false,'ค้นหารายการจอง')}}
$('lookupForm').onsubmit=event=>{event.preventDefault();lookupBooking(lookupMethod,$('lookupValue').value)};
function renderLookupResults(rows,method,value){$('lookupResults').classList.remove('hidden');if(!rows.length){const cardNotice=method==='citizen'&&lastCitizenId?`<div class="card-identity"><strong>อ่านบัตรสำเร็จ</strong><span>${escapeHtml(lastCardName||'ผู้ถือบัตร')} · CID •••••••••${lastCitizenId.slice(-4)}</span></div>`:'';$('lookupResults').innerHTML=cardNotice+'<div class="no-booking"><strong>ไม่พบรายการจองออนไลน์ของวันนี้</strong><p>สามารถเลือกรับคิว Walk-in ได้</p><button type="button" class="touch-button secondary" id="continueWalkin">เลือกบริการ Walk-in</button></div>';$('continueWalkin').onclick=async()=>{if(!lastCardName)lastCardName='ผู้รับบริการไม่ใช้บัตรประชาชน';updatePatientSummary();await kioskConfigReady;renderKioskMenu(null);show('servicePanel')};return}$('lookupResults').innerHTML=rows.map(row=>`<article class="booking-result"><strong>${escapeHtml(row.customer_display)} · ${escapeHtml(row.department_name)}</strong><span>${escapeHtml(row.reference_no)} · ${row.start_time.slice(0,5)}–${row.end_time.slice(0,5)} น.</span><button type="button" class="touch-button primary" data-checkin="${row.public_id}">ยืนยันว่ามาถึงแล้ว</button></article>`).join('');document.querySelectorAll('[data-checkin]').forEach(button=>button.onclick=async()=>{setBusy(button,true);try{const body=await request('kiosk-check-in',{token:button.dataset.checkin});renderTicket(body.ticket)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden');setBusy(button,false,'ยืนยันว่ามาถึงแล้ว')}})}
$('smartcardButton').onclick=async()=>{const button=$('smartcardButton');button.disabled=true;$('readerState').textContent='กำลังอ่านบัตร…';toast('กำลังอ่านบัตรประชาชน…');try{const response=await fetch('http://127.0.0.1:17890/read',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const body=await response.json();if(!response.ok||!body.data?.citizen_id)throw new Error(body.error||'อ่านบัตรไม่สำเร็จ');await acceptCard(body.data)}catch(error){$('readerState').textContent='อ่านบัตรไม่สำเร็จ';toast(error.message||'เครื่องอ่านบัตรยังไม่พร้อม กรุณาติดต่อเจ้าหน้าที่')}finally{button.disabled=false}};
function renderTicket(ticket){const start=String(ticket.start_time||'').slice(0,5),end=String(ticket.end_time||'').slice(0,5),queueNo=ticket.queue_no||'—';$('ticketNo').textContent=queueNo;$('ticketNo').classList.toggle('queue-number-long',Array.from(queueNo).length>7);$('ticketDepartment').textContent=ticket.department_name||'จุดบริการ';$('ticketService').textContent=ticket.service_name||'';$('ticketSlot').textContent=start&&end?`ช่วงลงทะเบียน ${start}–${end} น.`:'รอเจ้าหน้าที่แจ้งช่วงลงทะเบียน';$('ticketDate').textContent=ticket.slot_date?new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',dateStyle:'long'}).format(new Date(`${ticket.slot_date}T12:00:00+07:00`)):'';$('ticketReference').textContent=ticket.reference_no?`เลขอ้างอิง ${ticket.reference_no}`:'';const url=new URL('status.html',location.href);url.searchParams.set('t',ticket.public_id);$('statusLink').href=url.href;$('ticketToken').textContent=ticket.public_id;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('ticketQr').src=qr.createDataURL(7,10);show('ticketPanel');finishSeconds=60;$('finishCountdown').textContent=finishSeconds;finishTimer=setInterval(()=>{finishSeconds--;$('finishCountdown').textContent=finishSeconds;if(finishSeconds<=0)show('homePanel')},1000)}
async function stopCamera(){if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}$('video').classList.add('hidden');$('cameraIdle').classList.remove('hidden')}
function handleScanned(value){$('scanToken').value=tokenFrom(value);stopCamera();$('scanForm').requestSubmit()}
$('cameraButton').onclick=async()=>{if(!navigator.mediaDevices?.getUserMedia){$('scanError').textContent='เบราว์เซอร์นี้ไม่สามารถเปิดกล้องได้ กรุณาใช้เครื่องสแกนหรือกรอกรหัส';$('scanError').classList.remove('hidden');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});$('video').srcObject=stream;await $('video').play();$('video').classList.remove('hidden');$('cameraIdle').classList.add('hidden');const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null;const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let lastFallback=0;const scan=async time=>{if(!stream)return;if(detector){const codes=await detector.detect($('video')).catch(()=>[]);if(codes[0]){handleScanned(codes[0].rawValue);return}}else if(typeof jsQR==='function'&&time-lastFallback>120&&$('video').videoWidth){lastFallback=time;canvas.width=$('video').videoWidth;canvas.height=$('video').videoHeight;context.drawImage($('video'),0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);const code=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'});if(code?.data){handleScanned(code.data);return}}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch{$('scanError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้อง หรือใช้เครื่องสแกน/กรอกรหัสแทน';$('scanError').classList.remove('hidden')}};
let scannerBuffer='',scannerAt=0;document.addEventListener('keydown',event=>{if(event.target.matches('input'))return;const now=Date.now();if(now-scannerAt>100)scannerBuffer='';scannerAt=now;if(event.key==='Enter'&&scannerBuffer.length>8){handleScanned(scannerBuffer);scannerBuffer=''}else if(event.key.length===1)scannerBuffer+=event.key});
